module EvolutionaryPaths(\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] current_species,\n    input [15:0] fossils [0:7],\n    input [2:0] fossil_lengths [0:7],\n    input [2:0] current_length,\n    output reg possible,\n    output reg [7:0] assignment,\n    output reg done\n);\n    \n    // Parameters\n    localparam NUM_FOSSILS = 8'd8;\n    localparam MAX_STRING_LEN = 3'd8;\n    localparam CHAR_WIDTH = 2'd2;\n    \n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] PRECOMPUTE = 3'd1;\n    localparam [2:0] CHECK_ASSIGN = 3'd2;\n    localparam [2:0] VALID = 3'd3;\n    localparam [2:0] DONE_STATE = 3'd4;\n    \n    reg [2:0] state, next_state;\n    \n    // Precompute storage\n    reg valid_subseq [0:7];\n    reg can_chain [0:7][0:7];\n    \n    // Check assignment variables\n    reg [7:0] current_assign;\n    reg [7:0] chain1 [0:7];\n    reg [7:0] chain2 [0:7];\n    reg [2:0] chain1_len;\n    reg [2:0] chain2_len;\n    reg [2:0] chain1_lengths [0:7];\n    reg [2:0] chain2_lengths [0:7];\n    \n    // Sorting indices\n    reg [2:0] i, j;\n    reg [2:0] sort_i, sort_j;\n    reg [2:0] temp_index;\n    reg [2:0] temp_length;\n    \n    // General counters\n    reg [3:0] fossil_idx;\n    reg [7:0] assign_count;\n    reg valid_chain1, valid_chain2;\n    reg [3:0] check_step;\n    \n    // Subsequence check\n    reg [2:0] subseq_i, subseq_j;\n    reg [2:0] len1, len2;\n    reg [15:0] str1, str2;\n    reg is_subseq;\n    \n    // Cycle counters (for timeout prevention)\n    reg [31:0] cycle_count;\n    \n    integer k; // Loop iterator for initialization\n    \n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            possible <= 1'b0;\n            assignment <= 8'd0;\n            done <= 1'b0;\n            current_assign <= 8'd0;\n            assign_count <= 8'd0;\n            cycle_count <= 32'd0;\n            \n            for (k = 0; k < 8; k = k + 1) begin\n                valid_subseq[k] <= 1'b0;\n                chain1[k] <= 8'd0;\n                chain2[k] <= 8'd0;\n                chain1_lengths[k] <= 3'd0;\n                chain2_lengths[k] <= 3'd0;\n                for (j = 0; j < 8; j = j + 1) begin\n                    can_chain[k][j] <= 1'b0;\n                end\n            end\n        end else begin\n            cycle_count <= cycle_count + 32'd1;\n            done <= 1'b0; // Default done low\n            \n            case (state)\n                IDLE: begin\n                    possible <= 1'b0;\n                    assignment <= 8'd0;\n                    if (start) begin\n                        state <= PRECOMPUTE;\n                        fossil_idx <= 4'd0;\n                        cycle_count <= 32'd0;\n                    end\n                end\n                \n                PRECOMPUTE: begin\n                    // Check fossil vs current species\n                    is_subseq <= 1'b0;\n                    subseq_j <= 3'd0;\n                    subseq_i <= 3'd0;\n                    len1 <= fossil_lengths[fossil_idx];\n                    len2 <= current_length;\n                    str2 <= current_species;\n                    str1 <= fossils[fossil_idx];\n                    check_step <= 4'd0;\n                    \n                    if (check_step == 0) begin\n                        // Start subsequence check\n                        if (subseq_i < len1 && subseq_j < len2) begin\n                            if (str1[subseq_i*CHAR_WIDTH +: CHAR_WIDTH] == str2[subseq_j*CHAR_WIDTH +: CHAR_WIDTH]) begin\n                                subseq_i <= subseq_i + 3'd1;\n                            end\n                            subseq_j <= subseq_j + 3'd1;\n                        end\n                        \n                        if (subseq_j >= len2) begin\n                            valid_subseq[fossil_idx] <= (subseq_i == len1);\n                            fossil_idx <= fossil_idx + 4'd1;\n                            check_step <= 4'd0;\n                        end\n                        \n                        if (fossil_idx >= 8) begin\n                            state <= CHECK_ASSIGN;\n                            current_assign <= 8'd0;\n                            assign_count <= 8'd0;\n                        end\n                    end\n                end\n                \n                CHECK_ASSIGN: begin\n                    if (assign_count < 8'd255) begin\n                        current_assign <= current_assign + 8'd1;\n                        assign_count <= assign_count + 8'd1;\n                        \n                        // Split into chains\n                        chain1_len <= 3'd0;\n                        chain2_len <= 3'd0;\n                        for (k = 0; k < 8; k = k + 1) begin\n                            if (current_assign[k]) begin\n                                chain2[chain2_len] <= k;\n                                chain2_lengths[chain2_len] <= fossil_lengths[k];\n                                chain2_len <= chain2_len + 3'd1;\n                            end else begin\n                                chain1[chain1_len] <= k;\n                                chain1_lengths[chain1_len] <= fossil_lengths[k];\n                                chain1_len <= chain1_len + 3'd1;\n                            end\n                        end\n                        \n                        start_bubble_sort <= 1'b1;\n                        check_step <= 4'd1;\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                VALID: begin\n                    possible <= 1'b1;\n                    assignment <= current_assign;\n                    state <= DONE_STATE;\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n    \n    // Bubble sort process\n    reg start_bubble_sort;\n    reg sorting_done;\n    always @(posedge clk) begin\n        if (state == CHECK_ASSIGN && start_bubble_sort) begin\n            // Bubble sort for chain1\n            if (chain1_len > 1) begin\n                for (sort_i = 0; sort_i < chain1_len - 1; sort_i = sort_i + 1) begin\n                    for (sort_j = 0; sort_j < chain1_len - sort_i - 1; sort_j = sort_j + 1) begin\n                        if (chain1_lengths[sort_j] > chain1_lengths[sort_j + 1]) begin\n                            // Swap\n                            temp_index = chain1[sort_j];\n                            temp_length = chain1_lengths[sort_j];\n                            chain1[sort_j] <= chain1[sort_j + 1];\n                            chain1_lengths[sort_j] <= chain1_lengths[sort_j + 1];\n                            chain1[sort_j + 1] <= temp_index;\n                            chain1_lengths[sort_j + 1] <= temp_length;\n                        end\n                    end\n                end\n            end\n            \n            // Bubble sort for chain2 (similar process)\n            // ...\n            \n            start_bubble_sort <= 1'b0;\n            check_step <= 4'd2;\n        end\n    end\n    \n    // Chain verification logic\n    always @(posedge clk) begin\n        if (state == CHECK_ASSIGN && check_step == 2) begin\n            // Verify chain1 and chain2\n            // ...\n            \n            // If both chains valid\n            if (valid_chain1 && valid_chain2) begin\n                state <= VALID;\n            end else begin\n                state <= CHECK_ASSIGN;\n            end\n        end\n    end\n\nendmodule